void fill_row(int col, int mask, int next_mask, int ways) {
    if (col == m) {
        next_dp[next_mask] += ways;
        if (next_dp[next_mask] >= MOD) next_dp[next_mask] -= MOD;
        return;
    }
    if (mask & (1 << col)) {
